[Meta]
Description={argument name="description" default="Ultra realistic 8K UHD DSLR photo of a modern woman as Cleopatra"}
Reference_Likeness={argument name="reference likeness" default="100%"}
Resolution={argument name="resolution" default="8K UHD"}
Style={argument name="style" default="High-fashion editorial, sacred beauty ritual, ancient luxury realism"}

[Subject]
Identity={argument name="identity" default="Stylish beautiful woman as Cleopatra"}
Theme={argument name="theme" default="Divine femininity, power, timeless elegance"}
Angle={argument name="angle" default="Full-body editorial portrait, 3/4 angle"}
Body_Position={argument name="body position" default="Seated on edge of luxurious alabaster bath, angled sideways, one leg elegantly bent"}
Posture={argument name="posture" default="Relaxed yet regal"}
Hands={argument name="hands" default="One hand dipping into milky water, other hand holding golden perfume vial"}
Expression={argument name="expression" default="Serene, confident, hypnotic gaze, direct eye contact"}

[Appearance]
Outfit={argument name="outfit" default="Sheer ritual-style Cleopatra gown, ivory and gold lightweight translucent fabric, gold-thread embroidery, beaded edges, delicate straps, partially clinging/damp"}
Accessories={argument name="accessories" default="Thin gold arm cuffs, delicate finger rings, gold waist chain, light ceremonial collar necklace"}
Hair={argument name="hair" default="Sleek at crown, soft loose lengths, partially damp, reflecting candlelight"}
Makeup={argument name="makeup" default="Soft-glam Egyptian touch, elongated kohl eyeliner, bronze/rose eyeshadow with gold shimmer, dewy luminous skin, natural nude-rose lips"}

[Environment]
Location={argument name="location" default="Private royal bathing chamber, Cleopatra’s palace, Alexandria"}
Architecture={argument name="architecture" default="Towering stone columns, warm-toned marble walls, carved hieroglyphs"}
Midground={argument name="midground" default="Fragrant steam from brass bowls, flowing silk curtains, indoor fountains, tall candles, oil lamps, potted lotus and papyrus plants"}
Bath_Details={argument name="bath details" default="Carved alabaster tub, milk-infused water, floating lotus flowers, rose petals, fine gold flakes"}

[Ritual_Props]
Beauty_Products={argument name="beauty products" default="Golden vials (frankincense, myrrh, lotus oil), alabaster bowls (honey, olive oil, almond oil, Dead Sea salt), clay jars with kohl/mineral pigments"}
Linen={argument name="linen" default="Soft towels embroidered with Egyptian symbols"}
Tools={argument name="tools" default="Polished bronze hand mirror, gold ritual spoons/applicators, stone mortar and pestle"}

[Technical_Settings]
Camera={argument name="camera" default="DSLR"}
Lens={argument name="lens" default="50mm prime"}
Aperture={argument name="aperture" default="f/8 (Full-scene sharpness)"}
ISO={argument name="iso" default="100"}
Shutter_Speed={argument name="shutter speed" default="1/160s"}
Focus={argument name="focus" default="Extreme sharp focus, zero blur, no bokeh"}
Lighting={argument name="lighting" default="Warm cinematic candlelight, soft ambient palace lighting, golden skin highlights"}

[Micro_Details]
Elements={argument name="micro details" default="Visible rising steam, candle wax texture, flame reflections on gold, water droplets on skin, fabric translucency, floating petals"}

